    1.  function [Population, his_objs] = GeneticAlgorithm(N, D, G, P, V)
    2.      MaxFex = G*N; %最大评价次数
    3.      Fex=0; %当前评价次数
    4.      upper=min((5*1e6)/P, (1e6/P)+(1/D));
    5.      lower=max(0, (1/D)-(1e6/P));
    6.      Population = Initialization(N,D,Fex,lower,upper,P,V);
    7.      his_objs=[];
    8.      while (Fex<MaxFex)
    9.          %Fex
    10.         MatingPool=TournamentSelection(2,N,Population.objs);
    11.         Parentpool.decs=Population.decs(MatingPool,:);
    12.         Parentpool.objs=Population.objs(MatingPool,:);
    13.     %生成子代
    14.         OffDec=OperatorGA(Parentpool,lower,upper);
    15.         Offspring.decs=OffDec;
    16.      %评价
    17.         Offspring=evaluation(Offspring, P, V, D);
    18.         Fex=Fex+N;
    19.         Population=enviornmentalSelection(Population,Offspring);
    20.         his_objs=[his_objs,Population.objs];
    21.     end
    22. end

